def solve(input_g):
    """Apply rule: Horizontal fill if row has >=2 twos AND target cols all have 0 twos.
       Vertical fill if col has >=2 twos AND target rows all have 0 twos."""
    result = [row[:] for row in input_g]

    # Compute counts
    row_counts = {r: sum(1 for c in range(15) if input_g[r][c]==2) for r in range(9)}
    col_counts = {c: sum(1 for r in range(9) if input_g[r][c]==2) for c in range(15)}

    # Horizontal fills
    for r in range(9):
        twos = [(c, input_g[r][c]) for c in range(15) if input_g[r][c] == 2]
        if len(twos) >= 2 and row_counts[r] >= 2:
            for i in range(len(twos)-1):
                c1, v1 = twos[i]
                c2, v2 = twos[i+1]
                if all(col_counts[c] == 0 for c in range(c1+1, c2)):
                    for c in range(c1+1, c2):
                        result[r][c] = 1

    # Vertical fills
    for c in range(15):
        twos = [(r, input_g[r][c]) for r in range(9) if input_g[r][c] == 2]
        if len(twos) >= 2 and col_counts[c] >= 2:
            for i in range(len(twos)-1):
                r1, v1 = twos[i]
                r2, v2 = twos[i+1]
                if all(row_counts[r] == 0 for r in range(r1+1, r2)):
                    for r in range(r1+1, r2):
                        result[r][c] = 1

    return result

